//! Skills management CLI commands.//!//! Commands for listing, searching, and inspecting SKILL.md-based skills.//! List and info operate on the filesystem only; search queries the ClawHub registry.use std::path::Path;use clap::Subcommand;use crate::config::SkillsConfig;use crate::skills::catalog::SkillCatalog;use crate::skills::{SkillRegistry, SkillSource};#[derive(Subcommand, Debug, Clone)]pub enum SkillsCommand {    /// List all discovered skills    List {        /// Show detailed information (keywords, patterns, source path)        #[arg(short, long)]        verbose: bool,        /// Output as JSON        #[arg(long)]        json: bool,    },    /// Search ClawHub registry for skills    Search {        /// Search query        query: String,        /// Output as JSON        #[arg(long)]        json: bool,    },    /// Show detailed info about a specific skill    Info {        /// Skill name        name: String,        /// Output as JSON        #[arg(long)]        json: bool,    },}/// Run the skills CLI subcommand.